Answer

b) list.files() with full.names = TRUE returns complete paths. purrr::map_chr() applies readr::read_file() to each, returning a character vector of full texts. tools::file_path_sans_ext(basename(fls)) strips the path and .txt extension to produce clean names. Options (a), (c), and (d) are all incorrect: readLines() and scan() take a single file path, not a directory; read.csv() expects tabular data.

A Reusable tm-Based Pipeline


Code
clean_text_tm &lt;- function(text,
                           lowercase     = TRUE,
                           rm_markup     = TRUE,
                           rm_punct      = TRUE,
                           rm_numbers    = TRUE,
                           rm_stopwords  = TRUE,
                           stopword_lang = "english",
                           stem          = FALSE,
                           squish_ws     = TRUE) {
  out &lt;- text
  if (rm_markup)    out &lt;- stringr::str_remove_all(out, "&lt;[^&gt;]+&gt;")
  if (lowercase)    out &lt;- tolower(out)
  if (rm_punct)     out &lt;- tm::removePunctuation(out)
  if (rm_numbers)   out &lt;- tm::removeNumbers(out)
  if (rm_stopwords) out &lt;- tm::removeWords(out, tm::stopwords(stopword_lang))
  if (stem)         out &lt;- tm::stemDocument(out, language = stopword_lang)
  if (squish_ws)    out &lt;- tm::stripWhitespace(out)
  stringr::str_trim(out)
}

clean_text_tm(raw)


