    dplyr::ungroup()

# Build DFM with relative term frequencies
stylo_dfm &lt;- books_chunked |&gt;
    dplyr::group_by(doc_id) |&gt;
    dplyr::summarise(text = paste(text, collapse = " "), .groups = "drop") |&gt;
